3	#include <QDebug>
4	
5	SCPI::SCPI() :
6	    SCPINode(""),
7	    semQueue(QSemaphore(1)),
8	    semProcessing(QSemaphore(1))
9	{
10	    WAIexecuting = false;
11	    OPCsetBitScheduled = false;
12	    OPCQueryScheduled = false;
13	    OCAS = false;
14	    SESR = 0x00;
15	    ESE = 0xFF;
16	    processing = false;
17	
18	    add(new SCPICommand("*CLS", [=](QStringList) {
19	        SESR = 0x00;
20	        OCAS = false;
21	        OPCQueryScheduled = false;
22	        return SCPI::getResultName(SCPI::Result::Empty);
23	    }, nullptr));
24	
25	    add(new SCPICommand("*ESE", [=](QStringList params){
26	        unsigned long long newval;
27	        if(!SCPI::paramToULongLong(params, 0, newval) || newval >= 256) {
28	            return SCPI::getResultName(SCPI::Result::Error);
29	        } else {
30	            ESE = newval;
31	            return SCPI::getResultName(SCPI::Result::Empty);
32	        }
33	    }, [=](QStringList){
34	        return QString::number(ESE);
35	    }));
36	
37	    add(new SCPICommand("*ESR", nullptr, [=](QStringList){
38	        auto ret = QString::number(SESR);
39	        SESR = 0x00;
40	        return ret;
41	    }));
42	
43	    add(new SCPICommand("*OPC", [=](QStringList){
44	        // OPC command
45	        if(isOperationPending()) {
46	            OPCsetBitScheduled = true;
47	            OCAS = true;
48	        } else {
49	            // operation already complete
50	            setFlag(Flag::OPC);
51	        }
52	        return SCPI::getResultName(SCPI::Result::Empty);
53	    }, [=](QStringList) -> QString {
54	        // OPC query
55	        if(isOperationPending()) {
56	            // operation pending
57	            OPCQueryScheduled = true;
58	            OCAS = true;
59	            return SCPI::getResultName(SCPI::Result::Empty);
60	        } else {
61	            // no operation, can return immediately
62	            OCAS = false;
63	            return "1";
64	        }
65	    }));
66	
67	    add(new SCPICommand("*WAI", [=](QStringList){
68	        // WAI command
69	        if(isOperationPending()) {
70	            WAIexecuting = true;
71	        }
72	        return SCPI::getResultName(SCPI::Result::Empty);
73	    }, nullptr));
74	
75	    add(new SCPICommand("*LST", nullptr, [=](QStringList){
76	        QString list;
77	        createCommandList("", list);
78	        return list.trimmed();
79	    }));
80	}
81	
82	bool SCPI::match(QString s1, QString s2)
83	{
84	    if (s1.compare(s2, Qt::CaseInsensitive) == 0
85	     || s1.compare(alternateName(s2), Qt::CaseInsensitive) == 0
86	     || alternateName(s1).compare(s2, Qt::CaseInsensitive) == 0
87	     || alternateName(s1).compare(alternateName(s2), Qt::CaseInsensitive) == 0) {
88	        return true;
89	    } else {
90	        return false;
91	    }
92	}
93	
94	QString SCPI::alternateName(QString name)
95	{
96	    while(name.size() > 0 && name[name.size()-1].isLower()) {
97	        name.chop(1);
98	    }
99	    return name;
100	}
101	
102	bool SCPI::paramToDouble(QStringList params, int index, double &dest)
103	{
104	    if(index >= params.size()) {
105	        return false;
106	    }
107	    bool okay;
108	    dest = params[index].toDouble(&okay);
109	    return okay;
110	}
111	
112	bool SCPI::paramToULongLong(QStringList params, int index, unsigned long long &dest)
113	{
114	    if(index >= params.size()) {
115	        return false;
116	    }
117	    double res;
118	    bool okay = paramToDouble(params, index, res);
119	    if(res > std::numeric_limits<unsigned long long>::max() || res < std::numeric_limits<unsigned long long>::min()) {
120	        okay = false;
121	    }
122	    if(okay) {
123	        dest = res;
124	    }
125	    return okay;
126	}
127	
128	bool SCPI::paramToLong(QStringList params, int index, long &dest)
129	{
130	    if(index >= params.size()) {
131	        return false;
132	    }
133	    double res;
134	    bool okay = paramToDouble(params, index, res);
135	    if(res > std::numeric_limits<long>::max() || res < std::numeric_limits<long>::min()) {
136	        okay = false;
137	    }
138	    if(okay) {
139	        dest = res;
140	    }
141	    return okay;
142	}
143	
144	bool SCPI::paramToBool(QStringList params, int index, bool &dest)
145	{
146	    if(index >= params.size()) {
147	        return false;
148	    }
149	    bool okay = false;
150	    if(params[index] == "TRUE" || params[index] == "ON" || params[index] == "1") {
151	        dest = true;
152	        okay = true;
153	    } else if(params[index] == "FALSE" || params[index] == "OFF" || params[index] == "0") {
154	        dest = false;
155	        okay = true;
156	    }
157	    return okay;
158	}
159	
160	QString SCPI::getResultName(SCPI::Result r)
161	{
162	    switch (r) {
163	    case Result::Empty:
164	        return "";
165	    case Result::Error:
166	    default:
167	        return "ERROR";
168	    case Result::CmdError:
169	        return "CMD_ERROR";
170	    case Result::QueryError:
171	        return "QUERY_ERROR";
172	    case Result::ExecError:
173	        return "EXEC_ERROR";
174	    case Result::False:
175	        return "FALSE";
176	    case Result::True:
177	        return "TRUE";
178	    }
179	}
180	
181	void SCPI::input(QString line)
182	{
183	    semQueue.acquire();
184	    cmdQueue.append(line);
185	    semQueue.release();
186	    if(semProcessing.available()) {
187	        process();
188	    }
189	}
190	
191	void SCPI::process()
192	{
193	    semProcessing.acquire();
194	    semQueue.acquire();
195	    auto queueBuf = cmdQueue;
196	    semQueue.release();
197	    while(!WAIexecuting && !queueBuf.isEmpty()) {
198	        semQueue.acquire();
199	        auto cmd = cmdQueue.front();
200	        cmdQueue.pop_front();
201	        queueBuf = cmdQueue;
202	        semQueue.release();
203	        auto cmds = cmd.split(";");
204	        SCPINode *lastNode = this;
205	        for(auto cmd : cmds) {
206	            if(cmd.size() > 0) {
207	                if(cmd[0] == ':' || cmd[0] == '*') {
208	                    // reset to root node
209	                    lastNode = this;
210	                }
211	                if(cmd[0] == ':') {
212	                    cmd.remove(0, 1);
213	                }
214	                auto response = lastNode->parse(cmd, lastNode);
215	                if(response == getResultName(Result::Error)) {
216	                    setFlag(Flag::CME);
217	                } else if(response == getResultName(Result::QueryError)) {
218	                    setFlag(Flag::CME);
219	                } else if(response == getResultName(Result::CmdError)) {
220	                    setFlag(Flag::CME);
221	                } else if(response == getResultName(Result::ExecError)) {
222	                    setFlag(Flag::EXE);
223	                } else if(response == getResultName(Result::Empty)) {
224	                    // do nothing
225	                } else {
226	                    emit output(response);
227	                }
228	            }
229	        }
230	    }
231	    semProcessing.release();
232	}
233	
234	void SCPI::someOperationCompleted()
235	{
236	    if(!isOperationPending()) {
237	        // all operations are complete
238	        if(OCAS) {
239	            OCAS = false;
240	            if(OPCsetBitScheduled) {
241	                setFlag(Flag::OPC);
242	                OPCsetBitScheduled = false;
243	            }
244	            if(OPCQueryScheduled) {
245	                output("1");
246	                OPCQueryScheduled = false;
247	            }
248	        }
249	        if(WAIexecuting) {
250	            WAIexecuting = false;
251	            // process any queued commands
252	            process();
253	        }
254	    }
255	}
256	
257	void SCPI::setFlag(Flag flag)
258	{
259	    SESR |= ((int) flag);
260	}
261	
262	void SCPI::clearFlag(Flag flag)
263	{
264	    SESR &= ~((int) flag);
265	}
266	
267	bool SCPI::getFlag(Flag flag)
268	{
269	    return SESR & (int) flag;
270	}
271	
272	SCPINode::~SCPINode()
273	{
274	    if(parent) {
275	        parent->remove(this);
276	    }
277	    while(commands.size() > 0) {
278	        delete commands.front();
279	        commands.erase(commands.begin());
280	    }
281	    while(subnodes.size() > 0) {
282	        auto node = subnodes.front();
283	        remove(node);
284	        delete node;
285	    }
286	}
287	
288	bool SCPINode::addDoubleParameter(QString name, double &param, bool gettable, bool settable, std::function<void(void)> setCallback)
289	{
290	    auto cmd = settable ? [&param, setCallback](QStringList params) -> QString {
291	        if(SCPI::paramToDouble(params, 0, param)) {
292	            if(setCallback) {
293	                setCallback();
294	            }
295	            return SCPI::getResultName(SCPI::Result::Empty);
296	        } else {
297	            return SCPI::getResultName(SCPI::Result::Error);
298	        }
299	    } : (std::function<QString(QStringList)>) nullptr;
300	    auto query = gettable ? [&param](QStringList params) -> QString {
301	        Q_UNUSED(params)
302	        return QString::number(param);
303	    } : (std::function<QString(QStringList)>) nullptr;
304	    return add(new SCPICommand(name, cmd, query));
305	}
306	
307	bool SCPINode::addUnsignedIntParameter(QString name, unsigned int &param, bool gettable, bool settable, std::function<void(void)> setCallback)
308	{
309	    auto cmd = settable ? [&param, setCallback](QStringList params) -> QString {
310	        unsigned long long value;
311	        if(SCPI::paramToULongLong(params, 0, value)) {
312	            param = value;
313	            if(setCallback) {
314	                setCallback();
315	            }
316	            return SCPI::getResultName(SCPI::Result::Empty);
317	        } else {
318	            return SCPI::getResultName(SCPI::Result::Error);
319	        }
320	    } : (std::function<QString(QStringList)>) nullptr;
321	    auto query = gettable ? [&param](QStringList params) -> QString {
322	        Q_UNUSED(params)
323	        return QString::number(param);
324	    } : (std::function<QString(QStringList)>) nullptr;
325	    return add(new SCPICommand(name, cmd, query));
326	}
327	
328	bool SCPINode::addBoolParameter(QString name, bool &param, bool gettable, bool settable, std::function<void(void)> setCallback)
329	{
330	    auto cmd = settable ? [&param, setCallback](QStringList params) -> QString {
331	        if(SCPI::paramToBool(params, 0, param)) {
332	            if(setCallback) {
333	                setCallback();
334	            }
335	            return SCPI::getResultName(SCPI::Result::Empty);
336	        } else {
337	            return SCPI::getResultName(SCPI::Result::Error);
338	        }
339	    } : (std::function<QString(QStringList)>) nullptr;
340	    auto query = gettable ? [&param](QStringList params) -> QString {
341	        Q_UNUSED(params)
342	        return param ? SCPI::getResultName(SCPI::Result::True) : SCPI::getResultName(SCPI::Result::False);
343	    } : (std::function<QString(QStringList)>) nullptr;
344	    return add(new SCPICommand(name, cmd, query));
345	}
346	
347	bool SCPINode::addStringParameter(QString name, QString &param, bool gettable, bool settable, std::function<void ()> setCallback)
348	{
349	    auto cmd = settable ? [&param, setCallback](QStringList params) -> QString {
350	        if(params.size() == 1) {
351	            param = params[0];
352	            if(setCallback) {
353	                setCallback();
354	            }
355	            return SCPI::getResultName(SCPI::Result::Empty);
356	        } else {
357	            return SCPI::getResultName(SCPI::Result::Error);
358	        }
359	    } : (std::function<QString(QStringList)>) nullptr;
360	    auto query = gettable ? [&param](QStringList params) -> QString {
361	        Q_UNUSED(params)
362	        return param;
363	    } : (std::function<QString(QStringList)>) nullptr;
364	    return add(new SCPICommand(name, cmd, query, false));
365	}
366	
367	bool SCPINode::changeName(QString newname)
368	{
369	    if(newname == name) {
370	        return true;
371	    }
372	    if(parent) {
373	        if(parent->nameCollision(newname)) {
374	            // new name would result in a collision
375	            return false;
376	        }
377	    }
378	    name = newname;
379	    return true;
380	}
381	
382	void SCPINode::setOperationPending(bool pending)
383	{
384	    if(operationPending != pending) {
385	        operationPending = pending;
386	        if(!operationPending) {
387	            // operation completed, needs to perform check if all operations are complete
388	            auto root = this;
389	            while(root->parent) {
390	                root = root->parent;
391	            }
392	            auto scpi = dynamic_cast<SCPI*>(root);
393	            if(!scpi) {
394	                // dynamic cast failed, this is not actually a root node. The SCPI node likely
395	                // has no valid parent configured
396	            } else {
397	                scpi->someOperationCompleted();
398	            }
399	        }
400	    }
401	}
402	
403	bool SCPINode::isOperationPending()
404	{
