552	{
553	    if(cmd.isEmpty()) {
554	        return "";
555	    }
556	    auto cmdName = cmd.split(" ").front();
557	    auto splitPos = cmdName.indexOf(':');
558	    if(splitPos > 0) {
559	        // have not reached a leaf, find next subnode
560	        auto subnode = cmd.left(splitPos);
561	        for(auto n : subnodes) {
562	            if(SCPI::match(n->leafName(), subnode.toUpper())) {
563	                // pass on to next level
564	                return n->parse(cmd.right(cmd.size() - splitPos - 1), lastNode);
565	            }
566	        }
567	        // unable to find subnode
568	        return SCPI::getResultName(SCPI::Result::Error);
569	    } else {
570	        // no more levels, search for command
571	        QStringList params;
572	        params.append("");
573	        bool inQuotes = false;
574	        for(unsigned int i=0;i<cmd.length();i++) {
575	            if(cmd[i] == '\\') {
576	                // escape character, ignore
577	                continue;
578	            }
579	            // check if we are starting/stopping quotes
580	            if(cmd[i] == '"' || cmd[i] == '\'') {
581	                // check whether quotes are escaped
582	                if(i == 0 || cmd[i-1] != '\\') {
583	                    inQuotes = !inQuotes;
584	                    continue;
585	                }
586	            }
587	            if(inQuotes) {
588	                params.back().append(cmd[i]);
589	            } else {
590	                // not in quotes, handle splitting by space
591	                if(cmd[i] == ' ') {
592	                    if(params.back().length() > 0)
593	                    params.append("");
594	                } else {
595	                    params.back().append(cmd[i]);
596	                }
597	            }
598	        }
599	        // remove command name
600	        params.pop_front();
601	        bool isQuery = false;
602	        if (cmdName[cmdName.size()-1]=='?') {
603	            isQuery = true;
604	            cmdName.chop(1);
605	        }
606	        for(auto c : commands) {
607	            if(SCPI::match(c->leafName(), cmdName.toUpper())) {
608	                // save current node in case of non-root for the next command
609	                lastNode = this;
